import{_ as i,o as t,c as o,ao as n}from"./chunks/framework.DA_3JxoV.js";const h=JSON.parse('{"title":"How-to guides","description":"","frontmatter":{},"headers":[],"relativePath":"howto/index.md","filePath":"howto/index.md","lastUpdated":null}'),a={name:"howto/index.md"};function r(d,e,s,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="howto_index" tabindex="-1">How-to guides <a class="header-anchor" href="#howto_index" aria-label="Permalink to &quot;How-to guides {#howto_index}&quot;">​</a></h1><p>These pages are task recipes: short, runnable answers to &quot;how do I do X?&quot;. They assume you already know the basics — if you are new to MPSKit, start with <a href="/MPSKit.jl/previews/PR449/tutorials/first_groundstate#tutorial_first_groundstate">Your first ground state</a> instead. Each recipe below stands on its own, so feel free to jump straight to the one you need.</p><h2 id="States-and-operators" tabindex="-1">States and operators <a class="header-anchor" href="#States-and-operators" aria-label="Permalink to &quot;States and operators {#States-and-operators}&quot;">​</a></h2><p><strong><a href="/MPSKit.jl/previews/PR449/howto/states#howto_states">Constructing states</a></strong> — building <code>FiniteMPS</code>, <code>InfiniteMPS</code>, <code>WindowMPS</code>, and <code>MultilineMPS</code> objects.</p><ul><li><p>A finite MPS — random states, initializers and element types, per-site spaces, product states, and wrapping your own site tensors.</p></li><li><p>An infinite MPS — single- and multi-site unit cells, from spaces or from tensors.</p></li><li><p>A window MPS — a mutable finite region embedded in infinite environments.</p></li><li><p>A multiline MPS — stacking <code>InfiniteMPS</code> rows for boundary-MPS methods.</p></li><li><p>States with symmetries — building MPS with <code>Rep[G]</code> graded spaces.</p></li></ul><p><strong><a href="/MPSKit.jl/previews/PR449/howto/hamiltonians#howto_hamiltonians">Building Hamiltonians</a></strong> — assembling MPO Hamiltonians from local operators.</p><ul><li><p>Finite Hamiltonian from local terms — <code>FiniteMPOHamiltonian</code> from <code>inds =&gt; operator</code> pairs.</p></li><li><p>Infinite (translation-invariant) Hamiltonian — <code>InfiniteMPOHamiltonian</code> on a unit cell.</p></li><li><p>Converting between boundary conditions — open vs. periodic finite chains from an infinite Hamiltonian.</p></li><li><p>A window Hamiltonian — carving a finite interval out of an infinite Hamiltonian with <code>WindowMPOHamiltonian</code>.</p></li></ul><h2 id="Finding-ground-states" tabindex="-1">Finding ground states <a class="header-anchor" href="#Finding-ground-states" aria-label="Permalink to &quot;Finding ground states {#Finding-ground-states}&quot;">​</a></h2><p><strong><a href="/MPSKit.jl/previews/PR449/howto/groundstate_algorithms#howto_groundstate_algorithms">Ground-state algorithms</a></strong> — configuring <code>find_groundstate</code>.</p><ul><li><p>Get a ground state with defaults — letting <code>find_groundstate</code> pick an algorithm for you.</p></li><li><p>Configure finite-system DMRG — explicit <code>DMRG</code>/<code>DMRG2</code>, and chaining them with <code>&amp;</code>.</p></li><li><p>Configure infinite-system algorithms — <code>VUMPS</code>, <code>IDMRG</code>, and <code>IDMRG2</code>.</p></li><li><p>Refine convergence with GradientGrassmann — Riemannian gradient descent after a cheaper warm-up.</p></li><li><p>Control output and tolerances — <code>verbosity</code> levels and reusing <code>envs</code> between calls.</p></li></ul><p><strong><a href="/MPSKit.jl/previews/PR449/howto/bond_dimension#howto_bond_dimension">Controlling bond dimension</a></strong> — inspecting, growing, and shrinking bond dimension.</p><ul><li><p>Inspecting the current bond dimension — <code>left_virtualspace</code>/<code>right_virtualspace</code> and <code>dim</code>.</p></li><li><p>Growing bond dimension — <code>RandExpand</code> (no Hamiltonian needed) and <code>OptimalExpand</code>.</p></li><li><p>Reducing bond dimension — <code>SvdCut</code> and the in-place <code>changebonds!</code>.</p></li><li><p>Truncation schemes — <code>truncrank</code>, <code>trunctol</code>, <code>notrunc</code>, <code>truncspace</code>, and combining them with <code>&amp;</code>.</p></li><li><p>Growing during finite MPS optimization — <code>DMRG2</code> and the <code>trunc</code> keyword of <code>find_groundstate</code>.</p></li><li><p>Growing during infinite MPS optimization — <code>IDMRG2</code> and <code>VUMPSSvdCut</code>.</p></li><li><p>Chaining algorithms — composing bond-change and ground-state algorithms with <code>&amp;</code>.</p></li></ul><h2 id="Dynamics" tabindex="-1">Dynamics <a class="header-anchor" href="#Dynamics" aria-label="Permalink to &quot;Dynamics {#Dynamics}&quot;">​</a></h2><p><strong><a href="/MPSKit.jl/previews/PR449/howto/time_evolution#howto_time_evolution">Time evolution</a></strong> — real- and imaginary-time evolution of an MPS.</p><ul><li><p>Evolve a state through one time step — <code>timestep</code> with <code>TDVP</code>.</p></li><li><p>Evolve over a time span — <code>time_evolve</code> across a vector of time points.</p></li><li><p>Grow the bond dimension while evolving — <code>TDVP2</code> with a mandatory <code>trunc</code>.</p></li><li><p>Evolve an infinite state — single-site <code>TDVP</code> on an <code>InfiniteMPS</code>.</p></li><li><p>Imaginary-time evolution — <code>imaginary_evolution = true</code> to cool towards the ground state, with <code>normalize = true</code> to keep the state normalized.</p></li><li><p>Let the bond dimension adapt — <code>BUG</code> with a truncating <code>trunc</code>.</p></li><li><p>Build a time-evolution MPO — <code>make_time_mpo</code> (<code>WII</code>, <code>TaylorCluster</code>, <code>WI</code>) plus <code>approximate</code>, or <code>Zipup</code> for a single-sweep application.</p></li></ul><h2 id="Measurements" tabindex="-1">Measurements <a class="header-anchor" href="#Measurements" aria-label="Permalink to &quot;Measurements {#Measurements}&quot;">​</a></h2><p><strong><a href="/MPSKit.jl/previews/PR449/howto/observables#howto_observables">Computing observables</a></strong> — extracting physical quantities from an MPS.</p><ul><li><p>Local (one-site) expectation value — <code>expectation_value(ψ, i =&gt; O)</code>.</p></li><li><p>Multi-site (contiguous) expectation value — tensor-product operators on an index tuple.</p></li><li><p>Energy (full-MPO expectation value) — <code>expectation_value(ψ, H)</code> for a Hamiltonian MPO.</p></li><li><p>Two-point correlators — <code>correlator</code>, including a full correlation profile over a range.</p></li><li><p>Energy variance as a convergence check — <code>variance</code> as a diagnostic after a ground-state search.</p></li></ul><p><strong><a href="/MPSKit.jl/previews/PR449/howto/entanglement#howto_entanglement">Entanglement entropy and spectrum</a></strong> — reading off entanglement from the gauge tensors.</p><ul><li><p>Entanglement entropy at a single cut — <code>entropy(ψ, site)</code>.</p></li><li><p>Entropy profile across every cut — collecting <code>entropy</code> over all sites.</p></li><li><p>The entanglement spectrum — <code>entanglement_spectrum</code> as a sector-resolved vector.</p></li><li><p>Sector-resolved spectrum — indexing the spectrum by symmetry sector with <code>keys</code>/<code>pairs</code>.</p></li><li><p>Entanglement of an infinite MPS — <code>entropy</code>/<code>entanglement_spectrum</code> per unit-cell site.</p></li><li><p>Plotting the spectrum — the <code>entanglementplot</code> recipe (requires Plots.jl).</p></li></ul><h2 id="Excitations" tabindex="-1">Excitations <a class="header-anchor" href="#Excitations" aria-label="Permalink to &quot;Excitations {#Excitations}&quot;">​</a></h2><p><strong><a href="/MPSKit.jl/previews/PR449/howto/excitations#howto_excitations">Excited states</a></strong> — computing energy eigenstates beyond the ground state.</p><ul><li><p>Get a single excitation gap on an infinite chain — <code>QuasiparticleAnsatz</code> at a fixed momentum.</p></li><li><p>Scan the dispersion relation — passing a range of momenta in one call.</p></li><li><p>Target a symmetry sector — a charged quasiparticle via the <code>sector</code> keyword.</p></li><li><p>Excited states on a finite chain — <code>QuasiparticleAnsatz</code>, <code>FiniteExcited</code>, and the Chepiga ansätze.</p></li><li><p>Check excitation quality — <code>variance</code> on a quasiparticle state.</p></li><li><p>Domain-wall excitations — quasiparticles interpolating between two distinct ground states.</p></li></ul><h2 id="Performance-and-hardware" tabindex="-1">Performance and hardware <a class="header-anchor" href="#Performance-and-hardware" aria-label="Permalink to &quot;Performance and hardware {#Performance-and-hardware}&quot;">​</a></h2><p><strong><a href="/MPSKit.jl/previews/PR449/howto/parallelism_gpu#howto_parallelism_gpu">Parallelism and GPU support</a></strong> — tuning how MPSKit uses the hardware.</p><ul><li><p>Setting BLAS threads — <code>BLAS.set_num_threads</code> and the OpenBLAS/MKL difference.</p></li><li><p>Setting the MPSKit scheduler — <code>MPSKit.Defaults.set_scheduler!</code> with <code>:serial</code>/<code>:greedy</code>/<code>:dynamic</code>.</p></li><li><p>Diagnosing the thread layout — ThreadPinning.jl <code>threadinfo</code>.</p></li><li><p>Reducing memory usage — disabling multithreading to avoid <code>OutOfMemory</code>.</p></li><li><p>GPU support — the experimental Adapt-based path for moving states onto a GPU.</p></li></ul><h2 id="Missing-a-recipe?" tabindex="-1">Missing a recipe? <a class="header-anchor" href="#Missing-a-recipe?" aria-label="Permalink to &quot;Missing a recipe? {#Missing-a-recipe?}&quot;">​</a></h2><p>If the task you&#39;re after isn&#39;t listed here, please open an issue at <a href="https://github.com/QuantumKitHub/MPSKit.jl/issues" target="_blank" rel="noreferrer">QuantumKitHub/MPSKit.jl</a> describing what you&#39;re trying to do. Concrete task descriptions make the best new recipes.</p>',28)])])}const m=i(a,[["render",r]]);export{h as __pageData,m as default};
